import React, { useRef, useEffect, useState } from 'react';

interface ReasoningFrame {
  id: string;
  title: string;
  body: string;
  tokens: number;
}

interface ReasoningPanelProps {
  frames: ReasoningFrame[];
  isStreaming: boolean;
  onSeek?: (id: string) => void;
}

export const ReasoningPanel: React.FC<ReasoningPanelProps> = ({ frames, isStreaming, onSeek }) => {
  const scrollContainerRef = useRef<HTMLDivElement | null>(null);
  const isUserScrolledUpRef = useRef<boolean>(false);
  const lastFrameCountRef = useRef<number>(0);
  const [totalTokens, setTotalTokens] = useState<number>(0);

  // Calculate total tokens whenever frames change
  useEffect(() => {
    const total = frames.reduce((sum, frame) => sum + frame.tokens, 0);
    setTotalTokens(total);
  }, [frames]);

  // Auto-scroll logic: scroll to bottom if new frames added and user hasn't scrolled up
  useEffect(() => {
    const container = scrollContainerRef.current;
    if (!container) return;

    const frameCountChanged = frames.length > lastFrameCountRef.current;
    lastFrameCountRef.current = frames.length;

    if (frameCountChanged && !isUserScrolledUpRef.current && isStreaming) {
      // Smooth scroll to bottom
      container.scrollTo({
        top: container.scrollHeight,
        behavior: 'smooth',
      });
    }
  }, [frames.length, isStreaming]);

  const handleScroll = (): void => {
    const container = scrollContainerRef.current;
    if (!container) return;

    const { scrollTop, scrollHeight, clientHeight } = container;
    const isAtBottom = scrollHeight - scrollTop - clientHeight < 50; // 50px tolerance

    if (isAtBottom) {
      isUserScrolledUpRef.current = false;
    } else {
      isUserScrolledUpRef.current = true;
    }
  };

  return (
    <div className="reasoning-panel">
      <div className="reasoning-header">
        <span>Total Tokens: {totalTokens}</span>
        {isStreaming && <span className="streaming-indicator">Streaming...</span>}
      </div>
      <div
        ref={scrollContainerRef}
        className="reasoning-frames-container"
        onScroll={handleScroll}
      >
        {frames.map((frame: ReasoningFrame) => (
          <div
            key={frame.id}
            className="reasoning-frame"
            onClick={() => onSeek?.(frame.id)}
            role={onSeek ? 'button' : undefined}
            tabIndex={onSeek ? 0 : undefined}
          >
            <div className="frame-header">
              <span className="frame-title">{frame.title}</span>
              <span className="frame-tokens">{frame.tokens} tokens</span>
            </div>
            <div className="frame-body">{frame.body}</div>
          </div>
        ))}
      </div>
    </div>
  );
};
