import React, { useRef, useEffect, useCallback } from 'react';

export interface ReasoningFrame {
  id: string;
  title: string;
  body: string;
  tokens: number;
}

export interface ReasoningPanelProps {
  frames: ReasoningFrame[];
  isStreaming: boolean;
  onSeek?: (id: string) => void;
}

const ReasoningPanel: React.FC<ReasoningPanelProps> = ({
  frames,
  isStreaming,
  onSeek,
}) => {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const isUserScrollingRef = useRef<boolean>(false);

  // Calculate total tokens
  const totalTokens: number = frames.reduce(
    (acc: number, frame: ReasoningFrame): number => acc + frame.tokens,
    0
  );

  // Handle scroll events to detect user interaction
  const handleScroll = useCallback(() => {
    const container = containerRef.current;
    if (!container) return;

    const { scrollTop, scrollHeight, clientHeight } = container;
    const threshold = 50; // pixels from bottom

    // If user scrolled away from bottom, mark as manual scrolling
    if (scrollHeight - scrollTop - clientHeight > threshold) {
      isUserScrollingRef.current = true;
    } else {
      // If scrolled back to bottom, resume auto-scroll
      isUserScrollingRef.current = false;
    }
  }, []);

  // Auto-scroll to bottom when new frames are added, unless user is manually scrolling
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    if (!isUserScrollingRef.current) {
      container.scrollTop = container.scrollHeight;
    }
  }, [frames.length]);

  // Attach scroll listener
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    container.addEventListener('scroll', handleScroll);

    return () => {
      container.removeEventListener('scroll', handleScroll);
    };
  }, [handleScroll]);

  return (
    <div
      ref={containerRef}
      style={{
        height: '400px',
        overflowY: 'auto',
        border: '1px solid #ccc',
        padding: '8px',
        fontFamily: 'monospace',
        fontSize: '12px',
        lineHeight: '1.4',
      }}
    >
      {/* Header with total tokens */}
      <div
        style={{
          position: 'sticky',
          top: 0,
          backgroundColor: '#f0f0f0',
          padding: '4px 8px',
          marginBottom: '8px',
          fontWeight: 'bold',
          borderBottom: '1px solid #ccc',
          zIndex: 1,
        }}
      >
        Total Tokens: {totalTokens}
        {isStreaming && ' (Streaming...)'}
      </div>

      {/* Render frames */}
      {frames.map((frame: ReasoningFrame) => (
        <div
          key={frame.id}
          style={{
            padding: '4px 8px',
            marginBottom: '4px',
            backgroundColor: '#fafafa',
            borderLeft: '3px solid #007bff',
            cursor: onSeek ? 'pointer' : 'default',
          }}
          onClick={() => {
            if (onSeek) {
              onSeek(frame.id);
            }
          }}
        >
          <div style={{ fontWeight: 'bold', marginBottom: '2px' }}>
            {frame.title}
          </div>
          <div style={{ color: '#333', whiteSpace: 'pre-wrap' }}>
            {frame.body}
          </div>
          <div
            style={{
              marginTop: '2px',
              fontSize: '10px',
              color: '#888',
            }}
          >
            Tokens: {frame.tokens}
          </div>
        </div>
      ))}

      {/* Placeholder for streaming indicator */}
      {isStreaming && frames.length === 0 && (
        <div style={{ padding: '8px', color: '#888' }}>
          Generating...
        </div>
      )}
    </div>
  );
};

export default ReasoningPanel;
