import React, { useEffect, useRef, useCallback } from 'react';

export interface ReasoningFrame {
  id: string;
  title: string;
  body: string;
  tokens: number;
}

export interface ReasoningPanelProps {
  frames: ReasoningFrame[];
  isStreaming: boolean;
  onSeek?: (id: string) => void;
}

export function ReasoningPanel({ frames, isStreaming, onSeek }: ReasoningPanelProps): React.ReactElement {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const isUserScrolledRef = useRef<boolean>(false);
  const lastFrameIdRef = useRef<string | null>(null);

  // Track total tokens
  const totalTokens: number = frames.reduce((sum: number, frame: ReasoningFrame): number => sum + frame.tokens, 0);

  const handleScroll = useCallback((): void => {
    const container = containerRef.current;
    if (!container) {
      return;
    }
    const threshold: number = 50;
    const isAtBottom: boolean = container.scrollHeight - container.scrollTop - container.clientHeight < threshold;
    if (!isAtBottom) {
      isUserScrolledRef.current = true;
    } else {
      isUserScrolledRef.current = false;
    }
  }, []);

  // Scroll to bottom when new frames arrive, unless user manually scrolled up
  useEffect((): void => {
    if (frames.length === 0) {
      lastFrameIdRef.current = null;
      return;
    }

    const lastFrame: ReasoningFrame | undefined = frames[frames.length - 1];
    if (!lastFrame) {
      return;
    }

    const newFrameAdded: boolean = lastFrame.id !== lastFrameIdRef.current;
    lastFrameIdRef.current = lastFrame.id;

    if (newFrameAdded && !isUserScrolledRef.current) {
      const container = containerRef.current;
      if (container) {
        // Delay slightly to ensure DOM has rendered the new content
        requestAnimationFrame((): void => {
          container.scrollTo({
            top: container.scrollHeight,
            behavior: 'smooth',
          });
        });
      }
    }
  }, [frames.length]);

  const handleFrameClick = useCallback((id: string): void => {
    if (onSeek) {
      onSeek(id);
    }
  }, [onSeek]);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%', overflow: 'hidden' }}>
      <div
        ref={containerRef}
        onScroll={handleScroll}
        style={{
          flex: 1,
          overflowY: 'auto',
          padding: '8px',
          border: '1px solid #ccc',
          borderRadius: '4px',
        }}
      >
        {frames.map((frame: ReasoningFrame): React.ReactElement => {
          const formattedTokens: string = frame.tokens.toLocaleString();
          return (
            <div
              key={frame.id}
              onClick={(): void => handleFrameClick(frame.id)}
              style={{
                padding: '8px',
                marginBottom: '8px',
                borderBottom: '1px solid #eee',
                cursor: onSeek ? 'pointer' : 'default',
              }}
            >
              <div style={{ fontWeight: 'bold', marginBottom: '4px' }}>
                {frame.title}
              </div>
              <div style={{ whiteSpace: 'pre-wrap', fontSize: '14px', color: '#333' }}>
                {frame.body}
              </div>
              <div style={{ fontSize: '12px', color: '#888', marginTop: '4px', textAlign: 'right' }}>
                Tokens: {formattedTokens}
              </div>
            </div>
          );
        })}
      </div>
      <div
        style={{
          padding: '8px',
          borderTop: '1px solid #ccc',
          fontSize: '14px',
          fontWeight: 'bold',
          textAlign: 'right',
        }}
      >
        Total Tokens: {totalTokens.toLocaleString()}
        {isStreaming && ' (streaming...)'}
      </div>
    </div>
  );
}
