export interface ReasoningFrame {
  id: string;
  title: string;
  body: string;
  tokens: number;
}

export interface ReasoningPanelProps {
  frames: ReasoningFrame[];
  isStreaming: boolean;
  onSeek?: (id: string) => void;
}

export default function ReasoningPanel({
  frames,
  isStreaming,
  onSeek,
}: ReasoningPanelProps) {
  const listRef = useRef<HTMLDivElement | null>(null);
  const isUserScrolled = useRef<boolean>(false);
  const lastLength = useRef<number>(frames.length);

  const handleScroll = (): void => {
    const container = listRef.current;
    if (!container) return;

    const threshold = 20;
    const distanceToBottom = container.scrollHeight - container.scrollTop - container.clientHeight;
    const nearBottom = distanceToBottom < threshold;

    if (nearBottom) {
      isUserScrolled.current = false;
    } else {
      isUserScrolled.current = true;
    }
  };

  useEffect(() => {
    const currentLength = frames.length;
    if (currentLength > lastLength.current) {
      if (!isUserScrolled.current) {
        const container = listRef.current;
        if (container) {
          container.scrollTo({
            top: container.scrollHeight,
            behavior: "auto",
          });
        }
      }
    }
    lastLength.current = currentLength;
  }, [frames.length]);

  const totalTokens: number = frames.reduce(
    (sum: number, frame: ReasoningFrame): number => sum + frame.tokens,
    0
  );

  return (
    <div style={{ height: "100%", display: "flex", flexDirection: "column" }}>
      <div style={{ padding: 12, fontWeight: 600 }}>
        推理过程 - {isStreaming ? "生成中..." : "已完成"}
        <span style={{ marginLeft: 12, color: "#666" }}>
          共 {totalTokens} tokens
        </span>
      </div>
      <div
        ref={listRef}
        onScroll={handleScroll}
        style={{
          flex: 1,
          overflowY: "auto",
          padding: 12,
          display: "flex",
          flexDirection: "column",
          gap: 8,
          backgroundColor: "#fff",
        }}
      >
        {frames.map((frame: ReasoningFrame, index: number): JSX.Element => (
          <div
            key={frame.id}
            style={{
              padding: 12,
              border: "1px solid #e8e8e8",
              borderRadius: 6,
              cursor: onSeek ? "pointer" : "default",
              backgroundColor: "#fafafa",
            }}
            onClick={onSeek ? (): void => {
              onSeek(frame.id);
            } : undefined}
          >
            <div
              style={{
                fontWeight: 600,
                marginBottom: 8,
                display: "flex",
                justifyContent: "space-between",
              }}
            >
              <span>{frame.title}</span>
              <span style={{ fontSize: 12, color: "#888" }}>
                {frame.tokens} tokens
              </span>
            </div>
            <div style={{ fontSize: 14, color: "#333", whiteSpace: "pre-wrap" }}>
              {frame.body}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
