const ReasoningPanel: React.FC<ReasoningPanelProps> = ({ frames, isStreaming, onSeek }) => {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const isUserScrolledUpRef = useRef<boolean>(false);
  const lastFrameCountRef = useRef<number>(0);

  const handleScroll = (): void => {
    const el = containerRef.current;
    if (!el) return;
    const threshold = 50;
    const isAtBottom = el.scrollHeight - el.scrollTop - el.clientHeight < threshold;
    isUserScrolledUpRef.current = !isAtBottom;
  };

  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;

    if (frames.length > lastFrameCountRef.current) {
      lastFrameCountRef.current = frames.length;
      if (!isUserScrolledUpRef.current) {
        el.scrollTop = el.scrollHeight;
      }
    } else if (frames.length === lastFrameCountRef.current) {
      lastFrameCountRef.current = frames.length;
    } else {
      lastFrameCountRef.current = frames.length;
      isUserScrolledUpRef.current = false;
    }
  }, [frames.length]);

  const totalTokens: number = frames.reduce((acc: number, f: ReasoningFrame) => acc + f.tokens, 0);

  const [totalDisplay, setTotalDisplay] = useState<number>(totalTokens);
  useEffect(() => {
    setTotalDisplay(totalTokens);
  }, [totalTokens]);

  return (
    <div
      ref={containerRef}
      onScroll={handleScroll}
      style={{
        height: '400px',
        overflowY: 'auto',
        border: '1px solid #ccc',
        padding: '12px',
        fontFamily: 'monospace',
        position: 'relative',
      }}
    >
      <div style={{ marginBottom: '8px', fontWeight: 'bold', fontSize: '14px' }}>
        Total tokens: {totalDisplay}
        {isStreaming ? ' ⏳' : ' ✅'}
      </div>
      {frames.map((frame: ReasoningFrame) => (
        <div
          key={frame.id}
          style={{
            marginBottom: '16px',
            padding: '10px',
            borderLeft: '3px solid #007acc',
            backgroundColor: '#f9f9f9',
            cursor: onSeek ? 'pointer' : 'default',
            whiteSpace: 'pre-wrap',
            wordBreak: 'break-word',
          }}
          onClick={() => {
            if (onSeek) {
              onSeek(frame.id);
            }
          }}
        >
          <div style={{ fontWeight: 'bold', fontSize: '13px', marginBottom: '4px' }}>
            {frame.title}
          </div>
          <div style={{ fontSize: '12px', color: '#555', marginBottom: '4px' }}>
            tokens: {frame.tokens}
          </div>
          <div style={{ fontSize: '13px', lineHeight: '1.5' }}>
            {frame.body}
          </div>
        </div>
      ))}
      {isStreaming && (
        <div style={{ fontSize: '12px', color: '#888', fontStyle: 'italic' }}>
          Generating...
        </div>
      )}
    </div>
  );
};

export default ReasoningPanel;

