export const ReasoningPanel: React.FC<ReasoningPanelProps> = ({
  frames,
  isStreaming,
  onSeek,
}): React.ReactElement => {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const userScrolledUpRef = useRef<boolean>(false);

  const totalTokens: number = frames.reduce((sum: number, frame: ReasoningFrame): number => sum + frame.tokens, 0);

  useEffect((): void => {
    if (containerRef.current && !userScrolledUpRef.current) {
      containerRef.current.scrollTop = containerRef.current.scrollHeight;
    }
  }, [frames.length]);

  const handleScroll = (): void => {
    if (containerRef.current) {
      const { scrollTop, scrollHeight, clientHeight } = containerRef.current;
      // Consider "at bottom" within a small tolerance to account for rounding or layout shifts
      const isAtBottom: boolean = scrollHeight - scrollTop - clientHeight < 2;
      userScrolledUpRef.current = !isAtBottom;
    }
  };

  const resetAutoScroll = (): void => {
    userScrolledUpRef.current = false;
  };

  useEffect((): (() => void) => {
    if (!isStreaming) {
      resetAutoScroll();
    }
    // Cleanup not needed as this effect just resets on prop change
  }, [isStreaming]);

  const renderFrame = (frame: ReasoningFrame, index: number): React.ReactElement => (
    <div
      key={frame.id}
      style={{
        padding: '8px 0',
        borderBottom: index < frames.length - 1 ? '1px solid #eee' : 'none',
        cursor: onSeek ? 'pointer' : 'default',
      }}
      onClick={onSeek ? (): void => {
        onSeek(frame.id);
      } : undefined}
