      <div style={{ whiteSpace: 'pre-wrap', fontSize: '0.9em' }}>
        {frame.body}
      </div>
    </div>
  );

  return (
    <div
      ref={containerRef}
      onScroll={handleScroll}
      style={{
        maxHeight: '400px',
        overflowY: 'auto',
        padding: '16px',
        fontFamily: 'monospace',
        background: '#fafafa',
        border: '1px solid #ddd',
        borderRadius: '4px',
        position: 'relative',
      }}
