from collections import OrderedDict
import time
import functools


class LRUCache:
    def __init__(self, capacity: int):
        """Initialize the LRU cache with a given capacity."""
        self.capacity = capacity
        self.cache = OrderedDict()

    def get(self, key, default=None):
        """Return the value of the key if it exists, otherwise return default. Move the accessed key to the end to mark it as recently used."""
        if key in self.cache:
            self.cache.move_to_end(key)
            return self.cache[key]
        return default

    def put(self, key, value):
        """Insert or update the key-value pair in the cache. If the key exists, move it to the end. If the capacity is exceeded, remove the least recently used item (the first one)."""
        if key in self.cache:
            self.cache.move_to_end(key)
            self.cache[key] = value
        else:
            if len(self.cache) >= self.capacity:
                self.cache.popitem(last=False)
            self.cache[key] = value

    def __len__(self):
        """Return the number of items currently in the cache."""
        return len(self.cache)

    def __repr__(self):
        """Return a string representation of the cache showing key-value pairs in insertion/access order."""
        items = [f"{k}={v}" for k, v in self.cache.items()]
        return f"LRUCache([{', '.join(items)}], capacity={self.capacity})"


def timed(fn):
    """Decorator that prints the execution time of the function."""
    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        start_time = time.perf_counter()
        result = fn(*args, **kwargs)
        elapsed_time = time.perf_counter() - start_time
        print(f"Function '{fn.__name__}' executed in {elapsed_time:.6f} seconds")
        return result
    return wrapper

