import React, { useRef, useEffect, useState } from 'react';

interface ReasoningFrame {
  id: string;
  title: string;
  body: string;
  tokens: number;
}

interface ReasoningPanelProps {
  frames: ReasoningFrame[];
  isStreaming: boolean;
  onSeek?: (id: string) => void;
}

const ReasoningPanel: React.FC<ReasoningPanelProps> = ({ frames, isStreaming, onSeek }) => {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const isUserScrolled = useRef<boolean>(false);
  const lastFrameCount = useRef<number>(frames.length);

  const [totalTokens, setTotalTokens] = useState<number>(0);

  useEffect(() => {
    let sum = 0;
    for (let i = 0; i < frames.length; i++) {
      sum += frames[i].tokens;
    }
    setTotalTokens(sum);
  }, [frames]);

  const handleScroll = (): void => {
    const container = containerRef.current;
    if (!container) return;

    const { scrollTop, scrollHeight, clientHeight } = container;
    const threshold = 50;
    const isAtBottom = scrollHeight - scrollTop - clientHeight < threshold;

    if (isAtBottom) {
      isUserScrolled.current = false;
    } else {
      // Only set to true if user is scrolling up significantly
      // We check if scrollTop decreased compared to previous state implicitly by position
      // But standard approach: if not at bottom, user scrolled up.
      // However, to avoid false positives during streaming updates where scrollHeight grows,
      // we usually track if the user initiated a scroll up.
      // A simpler heuristic for this constraint: if not at bottom, pause auto-scroll.
      // But we need to resume when they scroll back down.
      // The standard pattern is: if distance from bottom > threshold, set userScrolled = true.
      // If distance from bottom < threshold, set userScrolled = false.
      if (scrollHeight - scrollTop - clientHeight >= threshold) {
         isUserScrolled.current = true;
      }
    }
  };

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    // Check if new frames were added
    const hasNewFrames = frames.length > lastFrameCount.current;
    lastFrameCount.current = frames.length;

    // Auto-scroll if streaming and user hasn't manually scrolled up
    if (hasNewFrames && isStreaming && !isUserScrolled.current) {
      // Use requestAnimationFrame to ensure DOM has updated before scrolling
      const rafId = requestAnimationFrame(() => {
        if (containerRef.current && !isUserScrolled.current) {
          containerRef.current.scrollTop = containerRef.current.scrollHeight;
        }
      });
      return () => cancelAnimationFrame(rafId);
    }
  }, [frames.length, isStreaming]);

  return (
    <div
      ref={containerRef}
      onScroll={handleScroll}
      style={{
        overflowY: 'auto',
        height: '100%',
        border: '1px solid #ccc',
        padding: '10px',
        fontFamily: 'monospace',
      }}
    >
      <div style={{ marginBottom: '10px', fontSize: '0.9em', color: '#666' }}>
        Total Tokens: {totalTokens}
      </div>
      {frames.map((frame: ReasoningFrame) => (
        <div
          key={frame.id}
          style={{
            marginBottom: '10px',
            padding: '10px',
            borderBottom: '1px solid #eee',
            cursor: onSeek ? 'pointer' : 'default',
          }}
          onClick={() => {
            if (onSeek) {
              onSeek(frame.id);
            }
          }}
        >
          <div style={{ fontWeight: 'bold', marginBottom: '5px' }}>
            {frame.title} <span style={{ fontSize: '0.8em', color: '#888' }}>({frame.tokens} tokens)</span>
          </div>
          <div style={{ whiteSpace: 'pre-wrap', fontSize: '0.9em' }}>
            {frame.body}
          </div>
        </div>
      ))}
    </div>
  );
};

export default ReasoningPanel;

