import { FunctionComponent, useEffect, useRef, useState, FC } from 'react';

export interface ReasoningFrame {
  id: string;
  title: string;
  body: string;
  tokens: number;
}

export interface ReasoningPanelProps {
  frames: ReasoningFrame[];
  isStreaming: boolean;
  onSeek?: (id: string) => void;
}

const ReasoningPanel: FC<ReasoningPanelProps> = ({ frames, isStreaming, onSeek }) => {
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const isUserScrolledUpRef = useRef<boolean>(false);

  const [totalTokens, setTotalTokens] = useState<number>(0);

  // Calculate total tokens
  useEffect(() => {
    const total = frames.reduce((sum, frame) => sum + frame.tokens, 0);
    setTotalTokens(total);
  }, [frames]);

  // Detect user scroll
  useEffect(() => {
    const container = scrollContainerRef.current;
    if (!container) return;

    const handleScroll = (): void => {
      const threshold = 50; // pixels from bottom
      const isAtBottom = container.scrollHeight - container.scrollTop <= container.clientHeight + threshold;
      isUserScrolledUpRef.current = !isAtBottom;
    };

    container.addEventListener('scroll', handleScroll);
    return () => container.removeEventListener('scroll', handleScroll);
  }, []);

  // Auto scroll to bottom when new frame is added, if user hasn't scrolled up
  useEffect(() => {
    if (!isUserScrolledUpRef.current && isStreaming && scrollContainerRef.current) {
      scrollContainerRef.current.scrollTop = scrollContainerRef.current.scrollHeight;
    }
  }, [frames.length, isStreaming]);

  // Handle click on frame title to seek
  const handleSeek = (id: string): void => {
    if (onSeek) {
      onSeek(id);
    }
  };

  return (
    <div
      ref={scrollContainerRef}
      style={{
        height: '400px',
        overflowY: 'auto',
        border: '1px solid #ccc',
        padding: '10px',
        backgroundColor: '#f9f9f9',
      }}
    >
      {frames.length === 0 ? (
        <div>No frames yet.</div>
      ) : (
        frames.map((frame) => (
          <div key={frame.id} style={{ marginBottom: '12px', paddingBottom: '8px', borderBottom: '1px solid #eee' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <strong style={{ color: '#333', cursor: 'pointer', textDecoration: 'underline' }} onClick={() => handleSeek(frame.id)}>
                {frame.title}
              </strong>
              <span style={{ fontSize: '12px', color: '#666' }}>{frame.tokens} tokens</span>
            </div>
            <div style={{ marginTop: '4px', color: '#555' }}>{frame.body}</div>
          </div>
        ))
      )}
      <div style={{ position: 'sticky', bottom: 0, backgroundColor: '#f9f9f9', paddingTop: '8px', borderTop: '1px solid #ccc', textAlign: 'right' }}>
        <span>Total: {totalTokens} tokens</span>
      </div>
    </div>
  );
};

export default ReasoningPanel;
